/**
 * Dependency resolution for AzureNode resources.
 *
 * A dependency is "fulfilled" when:
 *   - autoFromParent is true and the node has a parent of the matching targetType, OR
 *   - the node has an edge connected to a node of the matching targetType, OR
 *   - the node's properties[dep.key] holds a non-empty value.
 */

import type { AzureEdge, AzureNode, AzureNodeData, ResourceDependencyDef, ResourceTypeDefinition } from '../models';
import { getResourceType } from '../models';

export interface DependencyStatus {
  dep: ResourceDependencyDef;
  fulfilled: boolean;
  source?: 'parent' | 'edge' | 'property';
  resolvedNodeId?: string;
  /** When the resolved target's name does not match dep.requiredName. */
  nameMismatch?: { actual: string; expected: string | string[] };
}

/** Return the registered typeKey of a node (resolved through alias map). */
function nodeTypeKey(n: AzureNode): string {
  return (n.data as AzureNodeData).typeKey;
}

/** Test whether a node matches the target type (uses registry resolution). */
function matchesType(node: AzureNode, targetType: string): boolean {
  const tk = nodeTypeKey(node);
  if (tk === targetType) return true;
  // Resolve through registry: target may be a curated key while node uses a stencil key
  const def = getResourceType(tk);
  return def?.key === targetType;
}

/** Best-effort name extraction for a node (data.name → properties.name → label). */
function nodeName(n: AzureNode): string {
  const d = n.data as AzureNodeData & { label?: unknown };
  if (typeof d.name === 'string' && d.name.trim() !== '') return d.name;
  const propName = d.properties?.name;
  if (typeof propName === 'string' && propName.trim() !== '') return propName;
  if (typeof d.label === 'string') return d.label;
  return '';
}

function nameMatches(actual: string, required: string | string[]): boolean {
  return Array.isArray(required) ? required.includes(actual) : actual === required;
}

export function evaluateDependencies(
  node: AzureNode,
  allNodes: AzureNode[],
  edges: AzureEdge[],
): DependencyStatus[] {
  const def = getResourceType((node.data as AzureNodeData).typeKey);
  const deps = def?.dependencies ?? [];
  if (deps.length === 0) return [];

  const data = node.data as AzureNodeData;
  const results: DependencyStatus[] = [];

  for (const dep of deps) {
    let fulfilled = false;
    let source: DependencyStatus['source'] | undefined;
    let resolvedNodeId: string | undefined;

    let nameMismatch: DependencyStatus['nameMismatch'];

    // 1. autoFromParent
    if (dep.autoFromParent && node.parentId) {
      const parent = allNodes.find((n) => n.id === node.parentId);
      if (parent && matchesType(parent, dep.targetType)) {
        fulfilled = true;
        source = 'parent';
        resolvedNodeId = parent.id;
      }
    }

    // 2. Edge-connected resource
    if (!fulfilled) {
      const connectedIds = new Set<string>();
      for (const e of edges) {
        if (e.source === node.id) connectedIds.add(e.target);
        if (e.target === node.id) connectedIds.add(e.source);
      }
      const match = allNodes.find((n) => connectedIds.has(n.id) && matchesType(n, dep.targetType));
      if (match) {
        fulfilled = true;
        source = 'edge';
        resolvedNodeId = match.id;
      }
    }

    // 3. Explicit property reference
    if (!fulfilled) {
      const v = data.properties?.[dep.key];
      if (typeof v === 'string' && v.trim() !== '') {
        fulfilled = true;
        source = 'property';
      }
    }

    // 3.5 Indirect satisfaction via an intermediary type. e.g. a VM's
    // subnet dep accepts a network-interface as a one-hop wrapper: if
    // the VM is connected to a NIC, and the NIC is in a subnet (or
    // wired to one), the VM's subnet dep is considered satisfied.
    if (!fulfilled && dep.acceptVia && dep.acceptVia.length > 0) {
      const connectedIds = new Set<string>();
      for (const e of edges) {
        if (e.source === node.id) connectedIds.add(e.target);
        if (e.target === node.id) connectedIds.add(e.source);
      }
      for (const intermediate of allNodes) {
        if (!connectedIds.has(intermediate.id)) continue;
        const matchesIntermediate = dep.acceptVia.some((t) => matchesType(intermediate, t));
        if (!matchesIntermediate) continue;

        // Intermediate's parent matches targetType?
        const ipid = (intermediate as { parentId?: string }).parentId;
        if (ipid) {
          const ip = allNodes.find((n) => n.id === ipid);
          if (ip && matchesType(ip, dep.targetType)) {
            fulfilled = true;
            source = 'edge';
            resolvedNodeId = ip.id;
            break;
          }
        }

        // Or intermediate is edge-connected to a node of targetType?
        let foundEdge = false;
        for (const e of edges) {
          const otherId = e.source === intermediate.id
            ? e.target
            : e.target === intermediate.id ? e.source : null;
          if (!otherId) continue;
          const other = allNodes.find((n) => n.id === otherId);
          if (other && matchesType(other, dep.targetType)) {
            fulfilled = true;
            source = 'edge';
            resolvedNodeId = other.id;
            foundEdge = true;
            break;
          }
        }
        if (foundEdge) break;
      }
    }

    // 4. Validate required name on the resolved target (parent/edge only).
    if (fulfilled && dep.requiredName && resolvedNodeId) {
      const resolved = allNodes.find((n) => n.id === resolvedNodeId);
      if (resolved) {
        const actual = nodeName(resolved);
        if (!nameMatches(actual, dep.requiredName)) {
          fulfilled = false;
          nameMismatch = { actual, expected: dep.requiredName };
        }
      }
    }

    results.push({ dep, fulfilled, source, resolvedNodeId, nameMismatch });
  }

  return results;
}

/** True if any required dependency is unfulfilled. */
export function hasUnfulfilledRequired(statuses: DependencyStatus[]): boolean {
  return statuses.some((s) => s.dep.required && !s.fulfilled);
}

export type { ResourceTypeDefinition };
